 const source=batch();return {...source,id:code+':key-k:2026-11-25',code,name:code==='600000.SH'?'研究甲':'研究乙',familyId:'key-k-entry-16',ruleVersion:'frozen-v1',setupId:code+':2026-11-24',ruleIds:['regain-ma-20'],anchorDay:source.day,phase:'close',state:'near_B',qualified:true,sourceFetchedAt:'2026-11-25T07:10:00Z',actualDiscoveryAt:'2026-11-25T08:00:00Z',conditionKnownAfter:'2026-11-25T07:00:00Z',activeUntil:'2026-11-26T01:30:00Z',firstSeenAt:'2026-11-25T08:30:00Z',reference:{close:10,trigger:10.1,invalidation:9.5},chartUrls:Object.fromEntries([60,120].map(window=>[window,'/api/a-share-daily/entry-current-chart?'+new URLSearchParams({generation:source.generation,code,setup:'2026-11-24',window:String(window)})])),reasons:[],research:{rules:[{id:'regain-ma-20',label:'收回20日线',status:'effective',fit:stats(),recent:stats(),validation:stats()}]},observations:Object.fromEntries([1,2,3].map(h=>[h,observation(h)])),...patch};
