class Target{
 constructor(){this.events=new Map();}
 addEventListener(type,fn){if(!this.events.has(type))this.events.set(type,new Set());this.events.get(type).add(fn);}
 removeEventListener(type,fn){this.events.get(type)?.delete(fn);}
 dispatchEvent(event){for(const fn of this.events.get(event.type)||[])fn({...event,target:this,preventDefault:event.preventDefault||(()=>{})});}
}
class Element extends Target{
 constructor(tag='div'){super();this.tagName=tag;this.children=[];this.parentNode=null;this.dataset={};this.attrs={};this.own='';this.value='';this.hidden=false;this.disabled=false;this.open=false;}
 get textContent(){return this.own+this.children.map(node=>node.textContent).join('');}
 set textContent(value){this.replaceChildren();this.own=String(value);}
 get firstElementChild(){return this.children[0]||null;}
 append(...nodes){for(const node of nodes){if(node.parentNode){const old=node.parentNode.children;old.splice(old.indexOf(node),1);}node.parentNode=this;this.children.push(node);}}
 replaceChildren(...nodes){for(const node of this.children)node.parentNode=null;this.children=[];this.own='';this.append(...nodes);}
 setAttribute(name,value){this.attrs[name]=String(value);}
 getAttribute(name){return this.attrs[name]??null;}
 querySelector(selector){return find(this,node=>{if(['thead','summary'].includes(selector))return node.tagName===selector;const attr=selector.match(/^\[([^\]]+)\]$/);if(attr)return Object.hasOwn(node.attrs,attr[1]);const option=selector.match(/^option\[value="([^"]+)"\]$/);return option&&node.tagName==='option'&&node.value===option[1];});}
 cloneNode(deep){const node=new Element(this.tagName);node.dataset={...this.dataset};node.attrs={...this.attrs};node.own=this.own;node.value=this.value;if(deep)for(const child of this.children)node.append(child.cloneNode(true));return node;}
 focus(){this.focused=true;}
}
function find(root,fn){if(fn(root))return root;for(const child of root.children){const node=find(child,fn);if(node)return node;}return null;}
function all(root,fn){const nodes=fn(root)?[root]:[];for(const child of root.children)nodes.push(...all(child,fn));return nodes;}
function template(){
 const root=new Element('article');root.setAttribute('data-stock-desk-card','');
 for(const name of ['name','code','stage','reason','position','plan','chart','source','research','institution']){const node=new Element(['research','institution'].includes(name)?'details':'div');node.setAttribute('data-stock-desk-'+name,'');if(['research','institution'].includes(name)){const summary=new Element('summary');summary.textContent=name==='research'?'个股研究':'机构披露';const body=new Element();body.setAttribute('data-stock-desk-'+name+'-body','');node.append(summary,body);if(name==='research'){const analogue=new Element();analogue.setAttribute('data-stock-desk-analogue','');node.append(analogue);}}if(name==='plan')for(const key of ['title','levels','note']){const child=new Element(key==='title'?'h3':key==='levels'?'dl':'p');child.setAttribute('data-stock-desk-plan-'+key,'');node.append(child);}root.append(node);}
 const fragment=new Element();fragment.append(root);return {content:fragment};
}
function fixture(options={}){
 const env=new Target(),doc=new Target(),ids=new Map(),calls=[],intervals=new Map(),timeouts=new Map();let sequence=0,data=envelope(),response=null,clock=Date.parse('2026-11-25T09:00:00Z');
 for(const id of ['','date','status','source','market-position','error','tabs','candidates-tab','tracking-tab','filter-form','filters','phase','strategy','shape','query','candidates','tracking','count','refresh','results','empty','tracking-count','tracking-rows','tracking-empty'])ids.set('stock-desk'+(id?'-'+id:''),new Element());
 const table=new Element('table'),head=new Element('thead');table.append(head,ids.get('stock-desk-tracking-rows'));
 for(const value of ['close','a14']){const option=new Element('option');option.value=value;ids.get('stock-desk-phase').append(option);}
 ids.set('stock-desk-card-template',template());
 env.setInterval=fn=>{const id=++sequence;intervals.set(id,fn);return id;};env.clearInterval=id=>intervals.delete(id);env.setTimeout=(fn,ms)=>{const id=++sequence;timeouts.set(id,{fn:()=>{timeouts.delete(id);fn();},ms});return id;};env.clearTimeout=id=>timeouts.delete(id);
 env.fetch=async(path,init)=>{calls.push({path,init});return response?response(path,init):{ok:true,json:async()=>clone(data)};};
 doc.hidden=false;doc.defaultView=env;doc.getElementById=id=>ids.get(id);doc.createElement=tag=>new Element(tag);doc.createElementNS=(ns,tag)=>new Element(tag);
 const component=ui.mount(doc,{autoLoad:options.autoLoad??false,now:()=>clock});
 const el=id=>ids.get('stock-desk'+(id?'-'+id:''));
 return {env,doc,component,calls,intervals,timeouts,el,table,setPayload:value=>data=value,setResponse:fn=>response=fn,setNow:value=>clock=Date.parse(value),change:(id,value)=>{el(id).value=value;el(id).dispatchEvent({type:id==='query'?'input':'change'});},click:id=>el(id).dispatchEvent({type:'click'}),tick:async()=>{for(const fn of intervals.values())fn();await settle();}};
}
